run_script %{"script" => "local result, err = create_issue({
  title = "Reservations.book/2 crashes on empty list instead of returning an error",
  description = "While reading the code, found that Reservations.book/2 crashes (raises an exception) when called with an empty list argument, instead of returning an {:error, ...} tuple as the rest of the API does. Expected: book/2 should validate its input and return a proper error result for an empty list rather than crashing. Needs a fix plus a regression test covering the empty-list case.",
  severity = "error",
  scope = "app"
})
if result == nil then return { ok = false, error = err } end
return { ok = true, issue = result }"}

